package com.northstar.catalog;
import java.math.BigDecimal;import java.util.List;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/products") @CrossOrigin(origins="${FRONTEND_URL:http://localhost:5173}") public class ProductController{private final List<Product>products=List.of(new Product("chair-form","Form Lounge Chair","Furniture","Soft curves, solid oak, and a generous woven seat.",new BigDecimal("289.00"),"https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?auto=format&fit=crop&w=900&q=85","BESTSELLER",4.9,128),new Product("lamp-arc","Arc Table Lamp","Lighting","Warm light with an architectural silhouette.",new BigDecimal("119.00"),"https://images.unsplash.com/photo-1507473885765-e6ed057f782c?auto=format&fit=crop&w=900&q=85","NEW",4.8,74),new Product("vase-stone","Stoneware Vessel","Decor","Hand-finished stoneware with a tactile glaze.",new BigDecimal("64.00"),"https://images.unsplash.com/photo-1610701596007-11502861dcfa?auto=format&fit=crop&w=900&q=85",null,4.7,52),new Product("headphones-studio","Studio Headphones","Tech","Immersive sound, thoughtful comfort, minimal form.",new BigDecimal("179.00"),"https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=900&q=85","LIMITED",4.9,203));@GetMapping public List<Product>all(){return products;}@GetMapping("/{id}")public ResponseEntity<Product>one(@PathVariable String id){return products.stream().filter(p->p.id().equals(id)).findFirst().map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());}}
